// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzz the depositor address and the deposit amount
    function testFuzz_property(address actor, uint256 amount) public {
        // Keep amount in a wide admissible domain but ensure it's >= 1 wei
        // We will let the fuzzer find amount == MinDeposit (1 ether) if needed.
        vm.assume(actor != address(0));
        // Ensure actor has funds to send
        uint256 bal = bound(amount, 0, 10 ether);
        vm.deal(actor, bal);

        // Read MinDeposit from the contract
        uint256 minDep = c.MinDeposit();

        // We want to assert the general rule: for any actor and any v >= MinDeposit,
        // a Deposit of v increases balances(actor) by v.
        // So we only exercise the call when amount >= minDep; for other amounts the contract (both versions)
        // will ignore the deposit and balances stay the same, which also conforms to the general rule vacuously.

        uint256 before = c.balances(actor);

        bool ok;
        // Make the call as the actor with value = amount
        vm.prank(actor);
        try c.Deposit{value: bal}() {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 after = c.balances(actor);

        // The universal property we assert: if amount >= MinDeposit, then after == before + amount
        // For amounts < MinDeposit, after == before (Deposit ignored) — both are consistent with reference.
        // We encode this as a single assertTrue over c's public getters:
        if (amount >= minDep) {
            assertTrue(after == before + amount);
        } else {
            assertTrue(after == before);
        }
    }
}

