pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed params: actor and amount
    function testFuzz_property(address actor, uint256 amount) public {
        // keep amount in a wide but reasonable range and actor non-zero
        vm.assume(actor != address(0));
        amount = bound(amount, 0, 10 ether);

        // ensure actor has funds to send
        vm.deal(actor, amount);

        // read prior balance of that actor in contract
        uint256 beforeBalance = c.balances(actor);

        // perform Deposit from actor with provided amount
        vm.prank(actor);
        // execute the payable call, catching reverts is unnecessary as Deposit doesn't revert on < MinDeposit
        // but keep as direct call to exercise behavior
        (bool ok, ) = address(c).call{value: amount}(abi.encodeWithSignature("Deposit()"));
        // After call, read balance
        uint256 afterBalance = c.balances(actor);

        // General rule: if amount >= MinDeposit, then afterBalance == beforeBalance + amount
        // For the reference contract this holds for all inputs; the mutant (changing >= to >)
        // will break this when amount == MinDeposit.
        if (amount >= c.MinDeposit()) {
            assertTrue(afterBalance == beforeBalance + amount);
        } else {
            // if amount < MinDeposit, deposit should be ignored => balance unchanged
            assertTrue(afterBalance == beforeBalance);
        }
    }
}

