    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzzed parameters: actor and an arbitrary amount; we will constrain amount to be exactly MinDeposit
    function testFuzz_property(address actor, uint256 unusedAmount) public {
        // Keep actor non-zero to be a valid caller
        vm.assume(actor != address(0));

        // Read MinDeposit from the deployed reference contract c
        uint256 minDep = c.MinDeposit();

        // Ensure we test the case deposit == MinDeposit which the reference accepts (>=) and mutant rejects (>).
        // The fuzzer provides 'actor' and 'unusedAmount' but we force the deposit value to equal MinDeposit
        uint256 deposit = minDep;

        // Fund the actor so they can send deposit
        vm.deal(actor, deposit);

        // Make the call as the actor and observe whether Deposit returns (succeeds) or reverts/fails
        bool ok;
        vm.prank(actor);
        try c.Deposit{value: deposit}() {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE (one assert): On the correct reference contract, depositing exactly MinDeposit should succeed.
        assertTrue(ok);
    }
