import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzz params: actor (who calls Deposit) and an arbitrary probe key to check balances at some address
    function testFuzz_property(address actor, address probe) public {
        // keep addresses in the normal EVM range
        vm.assume(actor != address(0));
        vm.assume(probe != address(0));

        // Ensure actor has some ETH to send (we'll send zero but ensure account exists/has funds so call context is realistic)
        vm.deal(actor, 1 ether);

        // Record balance for probe before calling Deposit
        uint before = c.balances(probe);

        // Make actor call Deposit with 0 value
        vm.prank(actor);
        // call Deposit with value 0
        bool ok;
        try c.Deposit{value: 0}() {
            ok = true;
        } catch {
            ok = false;
        }

        // After Deposit with zero value, reference contract guarantees no balances change for ANY key.
        // We assert that balances(probe) is unchanged. This is true for the reference and will fail
        // on the mutant which accepts zero-value deposits and records them, changing balances for some keys.
        uint after = c.balances(probe);
        assertTrue(after == before);
    }
}

