pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzz params: depositor (sender) and another address victim
    function testFuzz_property(address depositor, address other, uint128 amount) public {
        // wide bounds but avoid same addresses for clarity
        vm.assume(depositor != address(0));
        vm.assume(other != address(0));

        // ensure different addresses to test the 'only caller's balance changes' property
        vm.assume(depositor != other);

        // bound amount to a reasonable Ether range
        amount = uint128(bound(amount, 0, 5 ether));

        // snapshot other balance before
        uint beforeOther = c.balances(other);

        // fund depositor so they can send value
        vm.deal(depositor, uint256(amount));
        vm.prank(depositor);
        // call Deposit with amount
        // If call reverts, ignore — we assert that other balance remains unchanged regardless
        try c.Deposit{value: uint256(amount)}() {
            // no-op
        } catch {
            // no-op on revert
        }

        // exactly one assertion: for the correct contract this should always hold;
        // the mutant (which removes MinDeposit) can be exploited (via malicious Log) to alter other addresses' balances during Deposit
        assertTrue(c.balances(other) == beforeOther);
    }
}

// Note: we do not deploy an adversarial external Log here because per instructions
// c was constructed with address(this) as the Log; the test leverages that and observes
// balances via the public getter. If the mutant accepts zero-value deposits it may
// lead to paths that allow external callbacks to mutate balances for other accounts
// when paired with a malicious Log; the reference contract preserves that Deposit
// never changes balances of addresses other than msg.sender.

