pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // Fuzz parameters: depositor (actor) and an arbitrary other address 'other'
    function testFuzz_property(address depositor, address other, uint128 amt) public {
        // Keep domain wide but avoid zero-address weirdness
        vm.assume(depositor != address(0));
        vm.assume(other != address(0));

        // bound amount to a reasonable range for vm.deal
        uint256 value = uint256(amt) % 1 ether; // allow zero as well to keep wide

        // Make sure depositor has funds to send
        vm.deal(depositor, 1 ether);

        // Snapshot other balance in contract storage before action
        uint256 beforeOther = c.balances(other);

        // Perform Deposit from depositor
        vm.prank(depositor);
        c.Deposit{value: value}();

        // Snapshot other balance after action
        uint256 afterOther = c.balances(other);

        // General rule: Deposit never changes balances of addresses other than msg.sender.
        // This must hold for the reference contract for all inputs, and the mutant that
        // removes the MinDeposit check can be made to violate it (via malicious Log re-entry)
        assertTrue(afterOther == beforeOther);
    }
}

