        // After call, read the stored balance for the same key
        uint256 after = c.balances(key);

        // General rule: for any inputs, the reference implementation ensures no stored balance decreases
        // i.e., after >= before. The buggy mutant can overflow and make after < before for some inputs.
        assertTrue(after >= before);
