        // deploy a reverter helper that will revert on receive if selected
        Reverter rev = new Reverter();

        address depositor = address(0xABCD);
        vm.deal(depositor, 20 ether);

        // make depositor deposit into c
        vm.prank(depositor);
        c.Deposit{value: depositAmt}();

        // choose whether to route the target call via the reverter (adversarial counterparty)
        bool useAdversary = (useAdversarySelector % 2 == 0);
        address target = useAdversary ? address(rev) : depositor;

        // send the contract some funds so it can pay out
        vm.deal(address(c), 20 ether);

        // ensure the depositor has the on-chain recorded balance set (only succeeds if depositAmt >= MinDeposit)
        vm.assume(depositAmt >= 1 ether);
        // ensure withdrawAmt is no larger than recorded balance to enter the if in CashOut
        vm.assume(withdrawAmt <= c.balances(depositor));

        // If we route to adversary, we need to make c think msg.sender is the adversary.
        // So we will have the adversary call CashOut while msg.sender is the adversary.
        // Prepare by ensuring adversary has no particular EOA balance — vm.prank will set msg.sender.

        bool ok;
        if (useAdversary) {
            // adversary (reverter) will revert when receiving Ether. Have it call CashOut.
            // Make sure c believes the adversary has the recorded balance by setting balances via depositing under that address.
            // We simulate deposit from adversary address so its recorded balance equals depositAmt.
            // Need to fund the adversary to pay the deposit
            vm.deal(address(rev), 20 ether);

            // perform deposit as the adversary
            vm.prank(address(rev));
            c.Deposit{value: depositAmt}();

            // ensure preconditions
            vm.assume(depositAmt >= 1 ether);
            vm.assume(withdrawAmt <= c.balances(address(rev)));

            // adversary attempts to withdraw; its receive will revert, so in reference the whole call reverts and balance should remain.
            try c.CashOut(withdrawAmt) {
                ok = true;
            } catch {
                ok = false;
            }

            // Reference property: when external transfer reverts, the recorded balance must be unchanged.
            // We assert that if the call reverted (ok == false), then the balance stayed equal to before.
            uint balAfter = c.balances(address(rev));
            // fetch expected before by knowing we deposited depositAmt
            uint balBefore = depositAmt;

            // single assertion: on the reference contract, whenever the external transfer fails (ok==false), the recorded balance equals balBefore
            assertTrue(!ok ? (balAfter == balBefore) : true);

        } else {
            // benign case: depositor (EOA) withdraws
            vm.prank(depositor);
            try c.CashOut(withdrawAmt) {
                ok = true;
            } catch {
                ok = false;
            }

            // For EOAs, external call succeeds; if it succeeded, balance must be reduced by withdrawAmt.
            uint balBefore = depositAmt;
            uint balAfter = c.balances(depositor);

            // Single assertion: if call reverted then balance unchanged; else decreased by withdrawAmt.
            if (!ok) {
                assertTrue(balAfter == balBefore);
            } else {
                assertTrue(balAfter == balBefore - withdrawAmt);
            }
        }
    }
